#!/data/data/com.termux/files/usr/bin/bash
# HAYU - SVGA tanpa Firebase Storage: file .svga disimpan di Firestore (dipecah, tanpa batas ukuran dari app)
# Jalankan di root repo:  bash pasang-svga-firestore.sh
set -e
cd "${REPO:-$PWD}"
D="app/src/main/java/com/hayu/app"
[ -f "$D/SvgaPlayer.kt" ] || { echo "❌ Jalankan di root repo Hayu-android (SVGA belum terpasang?)"; exit 1; }

T="$(mktemp -d)"
cat > "$T/b.b64" <<'B64_EOF'

B64_EOF
base64 -d "$T/b.b64" > "$T/b.tgz"
mkdir "$T/new" && tar xzf "$T/b.tgz" -C "$T/new"

BK="$HOME/.hayu-backup-fs-$(date +%H%M%S)"
FIXED=0
fix() {  # fix <file> <penanda>
  f="$1"; m="$2"
  if [ -f "$f" ] && grep -q -- "$m" "$f"; then
    echo "  ok         $f"
  else
    [ -f "$f" ] && { mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; }
    cp "$T/new/$f" "$f"
    echo "  DIPERBAIKI $f"
    FIXED=$((FIXED+1))
  fi
}
fix $D/SvgaStore.kt            "object SvgaStore"
fix $D/SvgaManagerActivity.kt  "SvgaStore.upload"
fix $D/SvgaPlayer.kt           "SvgaStore.isStored"
rm -rf "$T"

grep -q "object SvgaStore" $D/SvgaStore.kt && grep -q "SvgaStore.upload" $D/SvgaManagerActivity.kt && grep -q "SvgaStore.isStored" $D/SvgaPlayer.kt || { echo "❌ Verifikasi gagal"; exit 1; }
[ "$FIXED" -eq 0 ] && echo "✅ Sudah lengkap, tidak ada yang diubah." || echo "✅ $FIXED file dipasang (backup lama: $BK)"

if [ -d .git ] && [ "$FIXED" -gt 0 ]; then
  BR=$(git rev-parse --abbrev-ref HEAD)
  git add -A
  git commit -m "SVGA: simpan file di Firestore (tanpa Storage)" || true
  git pull --rebase --autostash origin "$BR" || { echo "⚠️ Konflik saat pull, selesaikan lalu: git rebase --continue && git push origin $BR"; exit 1; }
  git push origin "$BR"
  echo "✅ Terkirim ke origin/$BR"
fi
echo
echo "PENTING: tambahkan Firestore Rules untuk svgaAssets & svgaChunks (lihat pesan Claude)."
